/* Tarot card art (generated by tools/tarot_cards.py; edit the tool, not this file).
  TarotCards.meta: { w, h, order: [the 78 card ids], extra: [cards outside the 78, the Drowned Card], decks }; each deck's list
    holds the order, then the extra, then the back.
  TarotCards.load(deck) -> Promise of { w, h, card(id) -> RGBA Uint8ClampedArray of w*h*4, back() } once the deck's script
    (js/tarot/<deck>.js, a list of PNG data URIs) has loaded and every card decoded. Data URIs don't taint a canvas, so this works
    from file://.
  TarotCards.deckFor(rec): the deck key for a reading record ({deck, overlay}): the hedge-witch deck and its restylings by overlay, any
    other deck by its own key. Glass alpha: 255 glass, 254 lead, 253 lit lead.
*/
(function () {
  "use strict";
  const meta = {"w": 56, "h": 92, "order": ["major_00_fool", "major_01_magician", "major_02_high_priestess", "major_03_empress", "major_04_emperor", "major_05_hierophant", "major_06_lovers", "major_07_chariot", "major_08_strength", "major_09_hermit", "major_10_wheel_of_fortune", "major_11_justice", "major_12_hanged_man", "major_13_death", "major_14_temperance", "major_15_devil", "major_16_tower", "major_17_star", "major_18_moon", "major_19_sun", "major_20_judgement", "major_21_world", "wands_ace", "wands_2", "wands_3", "wands_4", "wands_5", "wands_6", "wands_7", "wands_8", "wands_9", "wands_10", "wands_page", "wands_knight", "wands_queen", "wands_king", "cups_ace", "cups_2", "cups_3", "cups_4", "cups_5", "cups_6", "cups_7", "cups_8", "cups_9", "cups_10", "cups_page", "cups_knight", "cups_queen", "cups_king", "swords_ace", "swords_2", "swords_3", "swords_4", "swords_5", "swords_6", "swords_7", "swords_8", "swords_9", "swords_10", "swords_page", "swords_knight", "swords_queen", "swords_king", "pentacles_ace", "pentacles_2", "pentacles_3", "pentacles_4", "pentacles_5", "pentacles_6", "pentacles_7", "pentacles_8", "pentacles_9", "pentacles_10", "pentacles_page", "pentacles_knight", "pentacles_queen", "pentacles_king"], "extra": ["drowned"], "decks": ["witch", "witch-bog", "witch-leaf", "witch-burnt", "witch-gilt", "witch-oilcloth", "glass", "deepwood", "gooddog", "goblin", "sailor", "frost", "ember"]};
  const cache = {};
  function script(src) {
    return new Promise((ok, bad) => {
      const s = document.createElement("script");
      s.src = src;
      s.onload = ok;
      s.onerror = bad;
      document.head.appendChild(s);
    });
  }
  function decode(uri) {
    return new Promise((ok, bad) => {
      const img = new Image();
      img.onload = () => {
        const c = document.createElement("canvas");
        c.width = img.width;
        c.height = img.height;
        const g = c.getContext("2d");
        g.drawImage(img, 0, 0);
        ok(g.getImageData(0, 0, img.width, img.height));
      };
      img.onerror = bad;
      img.src = uri;
    });
  }
  function load(deck) {
    if (!cache[deck]) {
      const have = window.TarotCardData && window.TarotCardData[deck];
      cache[deck] = (have ? Promise.resolve() : script(`js/tarot/${deck}.js`))
        .then(() => Promise.all(window.TarotCardData[deck].map(decode)))
        .then((imgs) => {
          const all = meta.order.concat(meta.extra || []), at = (i) => imgs[i].data;
          return { w: meta.w, h: meta.h, card: (id) => at(all.indexOf(id)), back: () => at(all.length) };
        });
    }
    return cache[deck];
  }
  function deckFor(rec) {
    if (rec.deck !== "witch") return rec.deck || "witch";
    return rec.overlay && rec.overlay !== "plain" ? `witch-${rec.overlay}` : "witch";
  }
  window.TarotCards = { meta, load, deckFor };
})();
